    # Daily aggregate per game, derived from bets (never out of sync with them).
    # Refresh after loading/changing bets:  REFRESH MATERIALIZED VIEW CONCURRENTLY daily_game_stats;
    # Days are UTC. ggr = total_staked - total_paid.
    op.execute(
        """
        CREATE MATERIALIZED VIEW daily_game_stats AS
        SELECT
            (b.placed_at AT TIME ZONE 'UTC')::date           AS stat_date,
            s.game_id                                        AS game_id,
            count(*)::integer                                AS total_bets,
            count(DISTINCT s.player_id)::integer             AS unique_players,
            sum(b.stake)::numeric(14, 2)                     AS total_staked,
            sum(b.payout)::numeric(14, 2)                    AS total_paid,
            (sum(b.stake) - sum(b.payout))::numeric(14, 2)   AS ggr
        FROM bets b
        JOIN game_sessions s ON s.id = b.session_id
        GROUP BY 1, 2
        """
    )
    # Unique index: required for REFRESH ... CONCURRENTLY, also serves lookups by day/game.
    op.execute(
        "CREATE UNIQUE INDEX uq_daily_game_stats_stat_date_game_id "
        "ON daily_game_stats (stat_date, game_id)"
    )


